window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-assignments.html"]="<!-- Settings: Auto-Assignment Rules -->\n<style>\n.asg-method{display:flex;gap:12px;margin-bottom:20px}\n.asg-method .card{flex:1;padding:16px;cursor:pointer;transition:all .15s}\n.asg-method .card.selected{border-color:var(--accent);background:rgba(79,70,229,.05)}\n.asg-method .card .emoji{font-size:24px;margin-bottom:6px}\n.asg-method .card .title{font-weight:700;font-size:14px}\n.asg-method .card .desc{font-size:12px;color:var(--muted);margin-top:4px}\n.asg-rule{display:flex;align-items:center;gap:12px;padding:12px 16px;border:1px solid var(--border);border-radius:8px;margin-bottom:8px;background:var(--card)}\n.asg-rule .label{flex:1;font-size:13px;font-weight:600}\n.asg-rule .sub{font-size:12px;color:var(--muted)}\n.toggle{position:relative;width:40px;height:22px;cursor:pointer}\n.toggle input{opacity:0;width:0;height:0}\n.toggle .slider{position:absolute;inset:0;background:#ccc;border-radius:22px;transition:.2s}\n.toggle .slider:before{content:'';position:absolute;width:16px;height:16px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s}\n.toggle input:checked+.slider{background:var(--accent)}\n.toggle input:checked+.slider:before{transform:translateX(18px)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">⏱️ SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">⚡ Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">🟢 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">🔵 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">💬 Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin:0 0 4px\">🔄 Auto-Assignment</h2>\n    <p style=\"color:var(--muted);font-size:13px;margin:0 0 20px\">Atur metode penugasan otomatis percakapan ke agen.</p>\n\n    <div class=\"asg-method\" id=\"asgMethod\">\n      <div class=\"card selected\" data-method=\"round-robin\" onclick=\"setMethod('round-robin')\">\n        <div class=\"emoji\">🔄</div>\n        <div class=\"title\">Round Robin</div>\n        <div class=\"desc\">Distribusi merata ke agen secara bergiliran.</div>\n      </div>\n      <div class=\"card\" data-method=\"manual\" onclick=\"setMethod('manual')\">\n        <div class=\"emoji\">🖐️</div>\n        <div class=\"title\">Manual</div>\n        <div class=\"desc\">Supervisor menugaskan agen secara manual.</div>\n      </div>\n    </div>\n\n    <h3 style=\"margin:16px 0 8px;font-size:14px\">Aturan Tambahan</h3>\n\n    <div class=\"asg-rule\">\n      <div>\n        <div class=\"label\">Skip agen offline</div>\n        <div class=\"sub\">Lewati agen yang sedang offline</div>\n      </div>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"skipOffline\" checked onchange=\"saveSettings()\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"asg-rule\">\n      <div>\n        <div class=\"label\">Batas kapasitas agen</div>\n        <div class=\"sub\">Jangan tugaskan jika agen sudah penuh</div>\n      </div>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"capacityLimit\" checked onchange=\"saveSettings()\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"asg-rule\">\n      <div>\n        <div class=\"label\">Re-assign saat shift berubah</div>\n        <div class=\"sub\">Pindahkan percakapan saat agen ganti shift</div>\n      </div>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"shiftReassign\" onchange=\"saveSettings()\"><span class=\"slider\"></span></label>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const cfg = DB.settings._assignment || {method:'round-robin',skipOffline:true,capacityLimit:true,shiftReassign:false};\n  renderMethod(cfg.method);\n  document.getElementById('skipOffline').checked = cfg.skipOffline;\n  document.getElementById('capacityLimit').checked = cfg.capacityLimit;\n  document.getElementById('shiftReassign').checked = cfg.shiftReassign;\n})();\n\nfunction renderMethod(m){\n  document.querySelectorAll('.asg-method .card').forEach(c=>{\n    c.classList.toggle('selected', c.dataset.method===m);\n  });\n}\nfunction setMethod(m){\n  renderMethod(m);\n  saveSettings();\n}\nfunction saveSettings(){\n  const active = document.querySelector('.asg-method .card.selected');\n  DB.settings._assignment = {\n    method: active ? active.dataset.method : 'round-robin',\n    skipOffline: document.getElementById('skipOffline').checked,\n    capacityLimit: document.getElementById('capacityLimit').checked,\n    shiftReassign: document.getElementById('shiftReassign').checked,\n  };\n  saveStore();\n  showToast('Pengaturan auto-assignment disimpan');\n}\n</script>\n";
